<template><aside class="summary card"><h3>Order summary</h3><div v-for="i in cart.items" :key="i.id" class="line"><span>{{i.name}} × {{i.quantity}}</span><b>{{format(i.price*i.quantity)}} EGP</b></div><hr/><div class="line"><span>Subtotal</span><b>{{format(cart.subtotal)}}</b></div><div class="line"><span>Shipping</span><b>{{cart.shipping?format(cart.shipping):'Free'}}</b></div><div class="line"><span>Tax</span><b>{{format(cart.tax)}}</b></div><div class="total line"><span>Total</span><b>{{format(cart.total)}} EGP</b></div></aside></template><script setup lang="ts">import {useCartStore} from '../../stores/cart';const cart=useCartStore();const format=(n:number)=>new Intl.NumberFormat('en-EG').format(n)</script><style scoped>.summary{padding:22px;height:max-content}.summary h3{margin-top:0}.line{display:flex;justify-content:space-between;gap:12px;padding:9px 0}.line span{color:#666}.summary hr{border:0;border-top:1px solid #eee}.total{border-top:1px solid #eee;margin-top:8px;padding-top:17px;font-size:17px}.total span{color:#111}</style>
